// GERADO: contornos simplificados dos estados do Brasil (dados públicos de limites estaduais).
// Projeção simples (equiretangular com correção de latitude). Use project(lon, lat) para marcar cidades.
export const MAP_WIDTH = 1052;
export const MAP_HEIGHT = 1023;

const K = 0.9659258262890683;
const LON0 = -74.2;
const LAT0 = 5.5;
const S = 25.8;
export function project(lon: number, lat: number): [number, number] {
  return [(lon - LON0) * K * S, (LAT0 - lat) * S];
}

